//! `include/dune.h` is generated by cbindgen and committed, so
//! building the crate never needs cbindgen. This test regenerates it
//! and fails when the committed copy is stale; set
//! `DUNE_FFI_BLESS=1` to rewrite it instead.

use std::path::Path;

#[test]
fn header_is_up_to_date() {
    let crate_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    let config = cbindgen::Config::from_file(crate_dir.join("cbindgen.toml")).unwrap();
    let bindings = cbindgen::Builder::new()
        .with_src(crate_dir.join("src/lib.rs"))
        .with_config(config)
        .generate()
        .expect("cbindgen failed on src/lib.rs");
    let mut fresh = Vec::new();
    bindings.write(&mut fresh);
    let fresh = String::from_utf8(fresh).unwrap();

    let committed_path = crate_dir.join("include/dune.h");
    if std::env::var_os("DUNE_FFI_BLESS").is_some() {
        std::fs::write(&committed_path, &fresh).unwrap();
        return;
    }
    let committed = std::fs::read_to_string(&committed_path).unwrap_or_default();
    // Line endings only (a Windows checkout with autocrlf).
    assert!(
        committed.replace("\r\n", "\n") == fresh,
        "include/dune.h is stale; regenerate with \
         DUNE_FFI_BLESS=1 cargo test -p dune-ffi --test header"
    );
}
